 	// -------------------------------------------------------------			

	error_reporting(0);
		
	include('../Includes/Configure.php'); 
	
	$Template		= file_get_contents("../Includes/Template.htm");
	
	$intCounter		= 0;
	$strKeywords	= explode(",", $Keywords);
	$strNavigation	= "<br>\n<small style='font-size:9pt;'>\n";
	
	while($intCounter != count($strKeywords))
		{
			$strNavigation .= "    <a href='../Articles/".str_replace(" ", "_", trim($strKeywords[$intCounter])).".php' title='Click here for the Index of all ".trim($strKeywords[$intCounter])." Articles...'>".trim($strKeywords[$intCounter])."</a>\n    <br>\n    <br>\n";
	
			$intCounter++;
		}
	
	$strNavigation .= "</small>";
	
	$fp				= fopen("../Includes/Navigation.php", "w");
	$fw				= fwrite( $fp, $strNavigation );
	fclose( $fp );

	$dirList			= opendir("../Articles");  				
	
	while (($dirPart	= @readdir($dirList)) == true) 
		{  											
			if($dirPart != "." && $dirPart != ".." && $dirPart != "index.php")
				{										
					unlink("../Articles/".$dirPart);
				}
		}

	$intCounter		= 0;
	
	while($intCounter != count($strKeywords))
		{
			$strIndex			= $Template;
			$strIndex			= str_replace("{META_TITLE}", $strKeywords[$intCounter]." | Index of All Articles in the ".$strKeywords[$intCounter]." Category", $strIndex);
			$strIndex			= str_replace("{ARTICLE_TITLE} - {ARTICLE_SUMMARY}", "Index of All Articles in the ".$strKeywords[$intCounter]." Category" , $strIndex);
					
			$dirList			= opendir("../Content");  				
	
			while (($dirPart	= @readdir($dirList)) == true) 
				{  											
					if($dirPart != "." && $dirPart != ".." && $dirPart != "index.php")
						{										
							$strTemp			= explode("<+>" ,file_get_contents("../Content/".$dirPart));
		
							$Keyword			= stripslashes(trim($strTemp[0]));
							
							If($Keyword	== trim($strKeywords[$intCounter]))
								{
									$Title		= stripslashes(trim($strTemp[1]));
									$Author		= stripslashes(trim($strTemp[2]));
									$Resource	= stripslashes(trim($strTemp[3]));
									
									$Summary	= str_replace("  ", " ", str_replace("nbsp", "", ereg_replace("[^a-z,A-Z,0-9, ]"," ",strip_tags(stripslashes(trim($strTemp[4]))))));

									$Body		= str_replace(chr(10), "<br>", stripslashes($strTemp[4]));
																	
									$strPage	= str_replace("{META_TITLE}", $strKeywords[$intCounter]." | ".$Title, $Template);
									$strPage	= str_replace("{ARTICLE_TITLE} - {ARTICLE_SUMMARY}", substr($Summary, 0, 256)."..." , $strPage);
									$strPage	= str_replace("{ARTICLE_TITLE}", "<b>\n".$Title."\n</b>\n<br>\n", $strPage);
									$strPage	= str_replace("{ARTICLE_AUTHOR}", "<small>\n".$Author."\n</small>\n<br>\n<br>\n", $strPage);
									$strPage	= str_replace("{ARTICLE_BODY}", $Body, $strPage);
									$strPage	= str_replace("{ARTICLE_ABOUT}", "<br><hr style='border-style: solid; width: 90%;'><br><p><i>".$Resource."</i></p>", $strPage);		
									
									$strIndexB .= "<br>\n<br>\n<b>\n<a href='../Articles/".str_replace(".txt", ".php", $dirPart)."'>".$Title."</a>\n</b>\n";
									$strIndexB .= "<br>\n<br>\n".substr($Summary, 0, 256)."<br>\n<small>\n<a href='../Articles/".str_replace(".txt", ".php", $dirPart)."'>Read More...</a>\n</small>\n<br>\n<br>\n";

									$fp			= fopen("../Articles/".str_replace(".txt", ".php", $dirPart), "w");
									$fw			= fwrite( $fp, $strPage );
									fclose( $fp );
									
									$strPage	= "";
								}
						}				
				}
					
			$strIndex	= str_replace("{ARTICLE_TITLE}", "<b>Index of All Articles in the ".$strKeywords[$intCounter]." Category</b>",  $strIndex);
			$strIndex	= str_replace("{ARTICLE_AUTHOR}", "", $strIndex);
			$strIndex	= str_replace("{ARTICLE_BODY}", "$strIndexB", $strIndex);
			$strIndex	= str_replace("{ARTICLE_ABOUT}", "", $strIndex);													
	
			$fp			= fopen("../Articles/".str_replace(" ", "_", trim($strKeywords[$intCounter])).".php", "w");
			$fw			= fwrite( $fp, $strIndex);
			fclose( $fp );
	
			$strIndex	= "";
			$strIndexB	= "";
				
			$intCounter++;							
		}	

		$_SESSION['Rebuild'] = true;

		include('RSS.php');			
		header('location: Rebuild.php');
?>
